import java.util.Set;
import java.util.HashSet;

class Solution {
    public int[] intersection(int[] nums1, int[] nums2) {
        Set<Integer> seen = new HashSet<>();
        for (int value : nums1) {
            seen.add(value);
        }

        Set<Integer> intersection = new HashSet<>();
        for (int value : nums2) {
            if (seen.contains(value)) {
                intersection.add(value);
            }
        }

        int[] answer = new int[intersection.size()];
        int index = 0;
        for (int value : intersection) {
            answer[index++] = value;
        }
        return answer;
    }
}

import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[] intersection(int[] nums1, int[] nums2) {
        Arrays.sort(nums1);
        Arrays.sort(nums2);

        List<Integer> result = new ArrayList<>();
        int i = 0;
        int j = 0;
        while (i < nums1.length && j < nums2.length) {
            if (nums1[i] < nums2[j]) {
                i++;
            } else if (nums1[i] > nums2[j]) {
                j++;
            } else {
                if (result.isEmpty() || result.get(result.size() - 1) != nums1[i]) {
                    result.add(nums1[i]);
                }
                i++;
                j++;
            }
        }

        int[] answer = new int[result.size()];
        for (int index = 0; index < result.size(); index++) {
            answer[index] = result.get(index);
        }
        return answer;
    }
}

import java.util.Arrays;
import java.util.Set;
import java.util.HashSet;

class Solution {
    public int[] intersection(int[] nums1, int[] nums2) {
        Arrays.sort(nums2);
        Set<Integer> result = new HashSet<>();
        for (int value : nums1) {
            if (Arrays.binarySearch(nums2, value) >= 0) {
                result.add(value);
            }
        }

        int[] answer = new int[result.size()];
        int index = 0;
        for (int value : result) {
            answer[index++] = value;
        }
        return answer;
    }
}

class Solution {
    public int[] intersection(int[] nums1, int[] nums2) {
        boolean[] inFirst = new boolean[1001];
        for (int value : nums1) {
            inFirst[value] = true;
        }

        boolean[] inBoth = new boolean[1001];
        for (int value : nums2) {
            if (inFirst[value]) {
                inBoth[value] = true;
            }
        }

        int count = 0;
        for (boolean present : inBoth) {
            if (present) {
                count++;
            }
        }

        int[] answer = new int[count];
        int index = 0;
        for (int value = 0; value < inBoth.length; value++) {
            if (inBoth[value]) {
                answer[index++] = value;
            }
        }
        return answer;
    }
}

import java.util.BitSet;

class Solution {
    public int[] intersection(int[] nums1, int[] nums2) {
        BitSet first = new BitSet(1001);
        BitSet second = new BitSet(1001);
        for (int value : nums1) {
            first.set(value);
        }
        for (int value : nums2) {
            second.set(value);
        }

        second.and(first);
        int[] answer = new int[second.cardinality()];
        int index = 0;
        for (int value = second.nextSetBit(0); value >= 0; value = second.nextSetBit(value + 1)) {
            answer[index++] = value;
        }
        return answer;
    }
}
